using Microsoft.AspNetCore.Mvc; using System.Text.Json; using RaceDay.MvC.Models; using RaceDay.MvC.Services;
namespace RaceDay.MvC.Controllers;
public class ParticipantController(RaceDayApiClient api):Controller { private IActionResult? Guard(){if(HttpContext.Session.GetInt32("UserID")==null)return RedirectToAction("Login","Account");if(HttpContext.Session.GetString("Role")!="Participant")return Forbid();return null;} public async Task<IActionResult> Index(){var g=Guard();if(g!=null)return g;var r=await api.Get<List<EventViewModel>>("api/events");ViewBag.Error=r.Error;return View((r.Data??new()).Where(e=>e.EventDate>=DateTime.Today).ToList());} public async Task<IActionResult> MyEnrolments(){var g=Guard();if(g!=null)return g;var r=await api.Get<List<EnrolmentViewModel>>("api/enrolments/me");ViewBag.Error=r.Error;return View(r.Data??new());} public async Task<IActionResult> MyResults(){var g=Guard();if(g!=null)return g;var r=await api.Get<List<ResultViewModel>>("api/results/me");var results=r.Data??new();var totals=results.GroupBy(x=>x.EventName??string.Empty).ToDictionary(x=>x.Key,x=>x.Count());foreach(var result in results)result.TotalFinishers=totals[result.EventName??string.Empty];ViewBag.Error=r.Error;return View(results);} [HttpPost,ValidateAntiForgeryToken] public async Task<IActionResult> Enrol(int eventCategoryId,string? raceNumber){var g=Guard();if(g!=null)return g;var r=await api.Send<JsonElement>(HttpMethod.Post,"api/enrolments",new{EventCategoryID=eventCategoryId,RaceNumber=raceNumber});TempData[r.Ok?"Success":"Error"]=r.Error??(r.Ok?"Enrolment submitted.":"Could not enrol.");return RedirectToAction(nameof(MyEnrolments));} [HttpPost,ValidateAntiForgeryToken] public async Task<IActionResult> Cancel(int id){var g=Guard();if(g!=null)return g;var r=await api.SendNoData(HttpMethod.Delete,$"api/enrolments/{id}");TempData[r.Ok?"Success":"Error"]=r.Error??"Enrolment cancelled.";return RedirectToAction(nameof(MyEnrolments));} }